import React from "react";
import { Input } from "@/components/ui/input";
import { Trash2 } from "lucide-react";
import HoldDownAdvisor from "./HoldDownAdvisor";

const money = (n) => `$${Number(n || 0).toFixed(2)}`;
const selectCls = "flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm";

const ITEM_TYPES = [
  { value: "panel", label: "Panel / Shape" },
  { value: "lettering", label: "Lettering" },
  { value: "3d_carving", label: "3D Carving" },
];
const MATERIALS = ["Acrylic", "Wood", "MDF", "Plywood", "PVC", "HDPE", "Aluminum", "Corian"];
const WORKHOLDING = [
  { value: "vacuum_full", label: "Full vacuum" },
  { value: "vacuum_zoned", label: "Zoned vacuum" },
  { value: "tape_glue", label: "Tape & glue" },
  { value: "screws", label: "Screws" },
  { value: "clamps", label: "Clamps" },
  { value: "none", label: "None" },
];

export default function CNCItemCard({ item, index, onChange, onRemove }) {
  const set = (patch) => onChange(index, patch);
  const numField = (key, label, placeholder) => (
    <label className="text-xs text-gray-500">
      {label}
      <Input
        type="number"
        placeholder={placeholder}
        value={item[key] ?? 0}
        onChange={(e) => set({ [key]: parseFloat(e.target.value) || 0 })}
      />
    </label>
  );

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4 space-y-3">
      <div className="flex items-start gap-2">
        <Input
          value={item.description || ""}
          placeholder="Part description"
          onChange={(e) => set({ description: e.target.value })}
        />
        <button onClick={() => onRemove(index)} className="text-gray-400 hover:text-red-600 p-2">
          <Trash2 className="w-4 h-4" />
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        <label className="text-xs text-gray-500">
          Item type
          <select
            value={item.item_type || "panel"}
            onChange={(e) => set({ item_type: e.target.value })}
            className={selectCls}
          >
            {ITEM_TYPES.map((t) => (
              <option key={t.value} value={t.value}>
                {t.label}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs text-gray-500">
          Material
          <select
            value={item.material_type || "Wood"}
            onChange={(e) => set({ material_type: e.target.value })}
            className={selectCls}
          >
            {MATERIALS.map((m) => (
              <option key={m} value={m}>
                {m}
              </option>
            ))}
          </select>
        </label>
        <label className="text-xs text-gray-500">
          Thickness
          <Input
            value={item.material_thickness || ""}
            placeholder='e.g. 1/4"'
            onChange={(e) => set({ material_thickness: e.target.value })}
          />
        </label>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {numField("quantity", "Qty")}
        {item.item_type === "3d_carving" ? (
          <>
            {numField("carve_area_sqin", "Carve area (sq in)")}
            {numField("carve_depth", "Carve depth (in)")}
            {numField("carve_speed_sqipm", "Carve sq in/min")}
          </>
        ) : item.item_type === "lettering" ? (
          <>
            {numField("num_letters", "# Letters")}
            {numField("letter_height", "Letter height (in)")}
            {numField("cut_speed_ipm", "Cut speed (ipm)")}
          </>
        ) : (
          <>
            {numField("length", "Length (in)")}
            {numField("width", "Width (in)")}
            {numField("cut_speed_ipm", "Cut speed (ipm)")}
          </>
        )}
        {numField("total_cut_length_inches", "Cut length override (in)")}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 border-t border-gray-100 pt-3">
        {numField("cutter_diameter_in", "Cutter dia. (in)")}
        {numField("smallest_detail_in", "Smallest detail (in)")}
        <label className="text-xs text-gray-500">
          Base workholding
          <select
            value={item.workholding_method || "none"}
            onChange={(e) => set({ workholding_method: e.target.value })}
            className={selectCls}
          >
            {WORKHOLDING.map((w) => (
              <option key={w.value} value={w.value}>
                {w.label}
              </option>
            ))}
          </select>
        </label>
      </div>

      <div className="flex flex-wrap gap-4">
        <label className="flex items-center gap-1.5 text-xs text-gray-600">
          <input
            type="checkbox"
            checked={!!item.creates_loose_pieces}
            onChange={(e) => set({ creates_loose_pieces: e.target.checked })}
          />
          Creates loose pieces
        </label>
        <label className="flex items-center gap-1.5 text-xs text-gray-600">
          <input
            type="checkbox"
            checked={!!item.force_enhanced}
            onChange={(e) => set({ force_enhanced: e.target.checked })}
          />
          Force enhanced hold-down
        </label>
      </div>

      <HoldDownAdvisor advice={item.hold_down} />

      <div className="flex flex-wrap gap-x-4 text-xs text-gray-500 border-t border-gray-100 pt-2">
        <span>
          Machine {Number(item.machine_time_hours || 0).toFixed(2)} hr · {money(item.machine_cost)}
        </span>
        <span>
          Setup {Number(item.setup_time_hours || 0).toFixed(2)} hr · {money(item.labor_cost)}
        </span>
        <span className="font-semibold text-gray-900 ml-auto">{money(item.item_total_cost)}</span>
      </div>
    </div>
  );
}

import React from "react";
import { ShieldCheck, AlertTriangle } from "lucide-react";

export default function HoldDownAdvisor({ advice }) {
  if (!advice) return null;
  const warn = advice.needed;
  return (
    <div
      className={`rounded-lg p-3 text-xs border ${
        warn ? "bg-amber-50 border-amber-300 text-amber-900" : "bg-emerald-50 border-emerald-200 text-emerald-900"
      }`}
    >
      <div className="flex items-center gap-1.5 font-semibold mb-1">
        {warn ? <AlertTriangle className="w-3.5 h-3.5" /> : <ShieldCheck className="w-3.5 h-3.5" />}
        Hold-Down Advisor
      </div>
      <p>{advice.recommendation}</p>
      {advice.reasons.length > 0 && (
        <ul className="list-disc list-inside mt-1 space-y-0.5 opacity-80">
          {advice.reasons.map((r, i) => (
            <li key={i}>{r}</li>
          ))}
        </ul>
      )}
      {advice.extra_hours > 0 && (
        <p className="mt-1 opacity-80">+{advice.extra_hours.toFixed(2)} hr added setup</p>
      )}
    </div>
  );
}

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

// Hold-Down Advisor — decides whether the item needs enhanced workholding.
export function holdDownAdvice(item) {
  const reasons = [];
  const detail = num(item.smallest_detail_in);
  const cutter = num(item.cutter_diameter_in);
  const loose = item.item_type === "lettering" || item.creates_loose_pieces;
  const base = item.workholding_method || "none";

  if (loose) reasons.push("Cut releases loose pieces at cut-through");
  if (detail > 0 && cutter > 0 && detail < cutter * 2)
    reasons.push(`Fine detail (${detail}") is under 2× cutter diameter`);
  if (["none", "clamps", "screws"].includes(base) && loose)
    reasons.push(`Base workholding (${base.replace("_", " ")}) will not retain small pieces`);
  if (base === "vacuum_full" && detail > 0 && detail < 0.5)
    reasons.push("Vacuum alone loses grip on narrow strokes");

  const needed = item.force_enhanced || reasons.length > 0;
  return {
    needed,
    reasons,
    recommendation: needed
      ? loose
        ? "Add tape-and-glue or onion-skin tabs over the vacuum, and plan a manual release pass."
        : "Add supplemental tape/glue or zoned vacuum before the finish pass."
      : "Base workholding is sufficient.",
    extra_hours: needed ? 0.25 * num(item.quantity, 1) : 0,
  };
}

export function calcCNCProject(project) {
  const machineRate = num(project.machine_rate_per_hour, 75);
  const laborRate = num(project.labor_rate, 45);
  const setupPct = num(project.setup_time_percentage, 20);

  const items = (project.items || []).map((raw) => {
    const item = { ...raw };
    const qty = num(item.quantity, 1);

    let cutHours = 0;
    if (item.item_type === "3d_carving") {
      const rate = num(item.carve_speed_sqipm, 10);
      const passes = Math.max(1, Math.ceil(num(item.carve_depth) / 0.25));
      cutHours = rate > 0 ? (num(item.carve_area_sqin) * passes) / rate / 60 : 0;
    } else {
      const speed = num(item.cut_speed_ipm, 50);
      const perimeter =
        num(item.total_cut_length_inches) ||
        (item.item_type === "lettering"
          ? num(item.num_letters) * num(item.letter_height) * 4
          : (num(item.length) + num(item.width)) * 2);
      cutHours = speed > 0 ? perimeter / speed / 60 : 0;
    }

    const advice = holdDownAdvice(item);
    item.hold_down = advice;
    item.machine_time_hours = cutHours * qty;
    item.setup_time_hours = (item.machine_time_hours * setupPct) / 100 + advice.extra_hours;
    item.machine_cost = item.machine_time_hours * machineRate;
    item.labor_cost = item.setup_time_hours * laborRate;
    item.item_total_cost = item.machine_cost + item.labor_cost;
    return item;
  });

  const total_machine_hours = items.reduce((s, i) => s + i.machine_time_hours, 0);
  const total_machine_cost = items.reduce((s, i) => s + i.machine_cost, 0);
  const fixed_setup_cost = num(project.fixed_setup_hours) * laborRate;
  const total_labor_cost = items.reduce((s, i) => s + i.labor_cost, 0) + fixed_setup_cost;
  const total_setup_hours =
    items.reduce((s, i) => s + i.setup_time_hours, 0) + num(project.fixed_setup_hours);

  return {
    items,
    totals: {
      total_machine_hours,
      total_setup_hours,
      total_machine_cost,
      fixed_setup_cost,
      total_labor_cost,
      total_cost: total_machine_cost + total_labor_cost,
    },
  };
}
